DROP POLICY IF EXISTS "cofounder_interests_read" ON "public"."cofounder_interests";
CREATE POLICY "cofounder_interests_read" ON "public"."cofounder_interests" FOR SELECT USING ((EXISTS ( SELECT 1 FROM cofounder_profiles p WHERE (((p.id = cofounder_interests.from_profile_id) OR (p.id = cofounder_interests.to_profile_id)) AND (p.tenant_id = public.current_tenant_id())))));
DROP POLICY IF EXISTS "cofounder_interests_write" ON "public"."cofounder_interests";
CREATE POLICY "cofounder_interests_write" ON "public"."cofounder_interests" FOR ALL USING ((EXISTS ( SELECT 1 FROM cofounder_profiles p WHERE ((p.id = cofounder_interests.from_profile_id) AND (p.tenant_id = public.current_tenant_id()))))) WITH CHECK ((EXISTS ( SELECT 1 FROM cofounder_profiles p WHERE ((p.id = cofounder_interests.from_profile_id) AND (p.tenant_id = public.current_tenant_id())))));

